#!/usr/bin/env python3
"""Reimplementation of src/program.cbl with GnuCOBOL 3 file semantics.

All files contain consecutive fixed-width binary records, not text lines.
Incomplete reads retain the unread portion of the previous record buffer.
Updates intentionally preserve the original program's unsigned arithmetic
and its non-atomic behavior when a later file operation fails.
"""

import errno
from contextlib import contextmanager
from pathlib import Path
import sys


class CobolFileError(Exception):
    def __init__(self, file, status, reason, implicit_close=False):
        self.file = file
        self.status = status
        self.reason = reason
        self.implicit_close = implicit_close
        super().__init__(reason)


class SequentialFile:
    def __init__(self, root, relative_path, size, name):
        self.path = root / relative_path
        self.relative_path = relative_path
        self.name = name
        self.size = size
        # FD storage is initially LOW-VALUES, not spaces.
        self.record = bytearray(size)
        self.stream = None
        self.read_done = False

    def io_error(self, error, implicit_close=False):
        if error.errno == errno.ENOENT:
            status, reason = 35, 'file does not exist'
        elif error.errno in (errno.EACCES, errno.EPERM, errno.EISDIR):
            status, reason = 37, 'permission denied'
        else:
            status, reason = 30, 'permanent file error'
        return CobolFileError(self, status, reason, implicit_close)

    @contextmanager
    def opened(self, mode):
        try:
            self.stream = self.path.open(mode, buffering=0)
        except OSError as error:
            raise self.io_error(error) from error
        self.read_done = False
        try:
            yield self
        except OSError as error:
            raise self.io_error(error, implicit_close=True) from error
        finally:
            self.stream.close()
            self.stream = None

    def read(self):
        data = self.stream.read(self.size)
        self.record[:len(data)] = data
        # A short read has status 04: usable for validation, but not REWRITE.
        self.read_done = len(data) == self.size
        return bool(data)

    def rewrite(self):
        read_done = self.read_done
        self.read_done = False
        if not read_done:
            raise CobolFileError(
                self, 43, 'READ must be executed first', implicit_close=True
            )
        self.stream.seek(-self.size, 1)
        self.stream.write(self.record)


def display_number(data):
    """Decode unsigned DISPLAY data as GnuCOBOL's decimal arithmetic does."""
    if data[0] == 255:
        return 10 ** len(data)
    if data[0] == 0:
        return -(10 ** len(data))
    start = 0
    while start < len(data) - 1 and (data[start] & 15) == 0:
        start += 1
    value = 0
    for byte in data[start:]:
        # GnuCOBOL's small DISPLAY conversion uses an unsigned 64-bit value.
        value = (value * 10 + byte - ord('0')) & ((1 << 64) - 1)
    return value


def balance_bytes(hundredths):
    # PIC 9(10) has no sign. Discard decimals and excess high-order digits.
    value = (abs(hundredths) // 100) % (10 ** 10)
    return f'{value:010d}'.encode('ascii')


def implicit_close_warning(file):
    print(
        f"libcob: warning: implicit CLOSE of {file.name} "
        f"('{file.relative_path}')", file=sys.stderr
    )


def process(root):
    accounts = SequentialFile(root, 'data/ACCOUNTS.DAT', 34, 'ACCOUNTS-FILE')
    books = SequentialFile(root, 'data/BOOKS.DAT', 28, 'BOOKS-FILE')
    transactions = SequentialFile(
        root, 'data/TRANSACTIONS.DAT', 22, 'TRANSACTIONS-FILE'
    )
    inputs = SequentialFile(root, 'src/INPUT.DAT', 22, 'INPUT-FILE')

    with inputs.opened('rb'):
        if not inputs.read():
            print('Error: Input file is empty')
            implicit_close_warning(inputs)
            return
        buyer = bytes(inputs.record[:4])
        seller = bytes(inputs.record[4:8])
        book_id = bytes(inputs.record[8:12])
        # Numeric-to-numeric MOVE changes spaces and NULs to zero digits,
        # preserves other bytes, and adds the two implied decimal places.
        amount = bytes(inputs.record[12:22]).translate(
            bytes.maketrans(b'\x00 ', b'00')
        )
        amount_hundredths = display_number(amount + b'00')

    buyer_found = seller_found = book_found = valid_owner = False
    with accounts.opened('rb'):
        while accounts.read():
            account_id = accounts.record[:4]
            if account_id == buyer:
                buyer_found = True
            if account_id == seller:
                seller_found = True
    with books.opened('rb'):
        while books.read():
            if books.record[:4] == book_id:
                book_found = True
                if books.record[24:28] == seller:
                    valid_owner = True
